/* a Cargo page: from the store if Cargo already has it, from the public API, or by letting Cargo's router fetch it (password-protected sites) */
const findCargoPage = (purl) => Object.values(store.getState().pages.byId || {}).find((p) => (p.purl || '').toLowerCase() === purl.toLowerCase() && typeof p.content === 'string');
const pageCache = {};
function cargoNavigate(path) {
  S.silent = true;
  try { history.pushState(history.state, '', path); window.dispatchEvent(new PopStateEvent('popstate', { state: history.state })); } finally { S.silent = false; }
}
async function loadPage(purl) {
  if (pageCache[purl]) return pageCache[purl];
  let p = findCargoPage(purl);
  if (!p) {
    try { const r = await fetch(`${API}/pages/${siteId()}/url/${encodeURIComponent(purl)}`); if (r.ok) { const j = await r.json(); if (j && typeof j.content === 'string') p = j; } } catch (e) {}
  }
  if (!p) {
    p = await new Promise((res) => {
      const un = store.subscribe(() => { const q = findCargoPage(purl); if (q) { un(); clearTimeout(to); res(q); } });
      const to = setTimeout(() => { un(); res(null); }, 6000);
      cargoNavigate('/' + purl);
    });
  }
  if (p) pageCache[purl] = p;
  return p;
}

/* products, for prices and options; the cart itself is Cargo's */
let PRODUCTS = null;
async function loadProducts() {
  if (PRODUCTS) return PRODUCTS;
  try { const j = await fetch(`${API}/commerce/${siteId()}/products`).then((x) => x.json()); PRODUCTS = {}; (j.data || []).forEach((p) => { PRODUCTS[p.product_id] = p; }); } catch (e) { PRODUCTS = {}; }
  return PRODUCTS;
}
const usd = (cents) => '$' + (Math.round(cents) / 100).toLocaleString('en-US', { minimumFractionDigits: cents % 100 ? 2 : 0 });

/* ---------- state ---------- */
const S = { route: 'index', filter: 'all', open: false, cart: 0, indexY: 0, from: null, held: 0, pShown: 0, navTok: 0, silent: false, sel: {} };

/* ---------- views ---------- */
function tileHTML(i, k) {
  const media = i.img ? `<img class="media${i.fit === 'contain' ? ' contain' : ''}" src="${i.img}"${setOf(i.img) ? ` srcset="${setOf(i.img)}" sizes="${SIZES_TILE}"` : ''} alt="${esc(i.title)}" loading="lazy" decoding="async">` : `<span class="ph">${esc(i.title)}</span>`;
  return `<a class="tile" data-k="${k}" data-cat="${esc(i.cat)}" href="/${esc(i.page)}" style="background:${i.dark ? '#0e0e0e' : (i.fit === 'contain' ? '#f2f2f2' : '#ececec')}">${media}<span class="cap frost"><span>${t(i)}</span>${i.sub ? `<span class="sub">${esc(i.sub)}</span>` : ''}</span></a>`;
}
function indexHTML() {
  if (!ITEMS.length) return `<section class="grid" id="grid" aria-label="Works"></section><p class="empty">No works yet. Tag a Cargo page with cat: to add it here.</p>`;
  return `<section class="grid" id="grid" aria-label="Works">${ITEMS.map(tileHTML).join('')}</section>`;
}
