const pageCat = (route) => { const it = ITEMS.find((i) => i.page === route); return it ? it.cat : (route === ABOUT ? 'about' : route); };
const pageCy = (route) => { const it = ITEMS.find((i) => i.page === route); return (it && it.cypher) || '000000'; };

/* ---------- routing and shared-element flights ---------- */
const view = $('#view');
{{flight}}
/* old addresses from the previous site; values: 'index', 'about', or 'burner' (the production burner page) */
const OLD = { about: 'about', 'about-1': 'about', art: 'index', burners: 'burner', shop: 'index', store: 'index' };
function oldTarget(seg) {
  const t = OLD[seg.toLowerCase()];
  if (!t) return null;
  if (t === 'index') return 'index';
  if (t === 'about') return ABOUT || null;
  if (t === 'burner') { const b = ITEMS.find((i) => /^burner/i.test(i.page) && !/1-?of-?1/i.test(i.page) && !/1-1$/.test(i.page)); return b ? b.page : 'index'; }
  return null;
}
function routeFromPath() {
  let seg = decodeURIComponent(location.pathname.replace(/^\/+/, '').split('/')[0] || '');
  if (!seg) return 'index';
  const known = seg === ABOUT || ITEMS.some((i) => i.page === seg) || seg === 'cart';
  if (!known) { const t = oldTarget(seg); if (t) { history.replaceState(history.state, '', t === 'index' ? '/' : '/' + t); seg = t; } }
  return seg;
}
function renderIndex() {
  S.route = 'index';
  view.innerHTML = indexHTML(); applyFilter(); setDate(today()); setCat(S.filter);
}
async function openPage(purl, tileEl) {
  closePanel();
  const tok = ++S.navTok;
  const item = ITEMS.find((i) => i.page === purl) || null;
  const fromRect = tileEl ? tileEl.getBoundingClientRect() : null;
  const r0 = tileEl ? radiusOf(tileEl) : 18;
  if (S.route === 'index') S.indexY = window.scrollY;
  S.held = S.pShown;
  if (tileEl) tileEl.style.opacity = '.6';
  const [p] = await Promise.all([loadPage(purl), loadProducts()]);
  if (tok !== S.navTok) return;
  if (tileEl) tileEl.style.opacity = '';
  if (!p) { toast('page not found'); history.replaceState(null, '', '/'); renderIndex(); return; }
  S.route = purl;
  view.innerHTML = pageHTML(p, item);
  setDate(pageCy(purl)); setCat(pageCat(purl)); wireDetail();
  window.scrollTo(0, 0);
  if (!fromRect || reduce || !item || !item.img) { if (!reduce) view.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 320, easing: 'ease', fill: 'backwards' }); return; }
  const target = view.querySelector('.img.first');
  if (!target) return;
  target.style.visibility = 'hidden';
  view.querySelectorAll('.info, .buy, .imgs .img').forEach((el) => el.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 520, delay: 140, easing: 'ease', fill: 'both' }));
  flight(fromRect, target, item.img, item.fit, item.dark ? '#0e0e0e' : (item.fit === 'contain' ? '#f2f2f2' : '#e4e0d8'), r0, radiusOf(target), () => { target.style.visibility = ''; });
}
function closePage() {
  ++S.navTok;
  const page = S.route;
  const hero = view.querySelector('.img.first');
  const heroRect = hero ? hero.getBoundingClientRect() : null;
  const r0 = hero ? radiusOf(hero) : 18;
  const item = ITEMS.find((i) => i.page === page);
  S.held = S.pShown;
  renderIndex();
  window.scrollTo(0, S.indexY || 0);
  if (reduce || !item || !item.img || !heroRect || heroRect.bottom < 0) { view.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 300, fill: 'backwards' }); return; }
  const tile = view.querySelector(`.tile[data-k="${ITEMS.indexOf(item)}"]`);
  if (!tile || tile.hidden) return;
  tile.classList.add('ghost');
  view.querySelectorAll('.tile:not(.ghost)').forEach((el) => el.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 480, delay: 120, fill: 'both' }));
  flight(heroRect, tile, item.img, item.fit, item.dark ? '#0e0e0e' : (item.fit === 'contain' ? '#f2f2f2' : '#e4e0d8'), r0, radiusOf(tile), () => tile.classList.remove('ghost'));
}
{{info}}
view.addEventListener('pointerover', (e) => { const tile = e.target.closest('a.tile'); if (tile) { const r = tile.getAttribute('href').slice(1); loadPage(r); } });
/* every in-site link: tiles, index rows, home, and links inside page text */
root.addEventListener('click', (e) => {
  const a = e.target.closest('a[href]');
  if (!a || e.defaultPrevented || e.metaKey || e.ctrlKey || e.shiftKey || a.target === '_blank') return;
  const href = a.getAttribute('href');
  if (/^(mailto:|tel:|https?:)/i.test(href) && !href.startsWith(location.origin)) return;
  const url = new URL(href, location.href);
  if (url.origin !== location.origin) return;
  const r = decodeURIComponent(url.pathname.replace(/^\/+/, '').split('/')[0] || '') || 'index';
  e.preventDefault();
  if (a.id === 'home' || r === 'index') {
    closePanel(); S.held = 0;
    if (S.route !== 'index') { history.pushState(null, '', '/'); closePage(); S.held = 0; requestAnimationFrame(() => window.scrollTo({ top: 0, behavior: reduce ? 'auto' : 'smooth' })); }
    else window.scrollTo({ top: 0, behavior: reduce ? 'auto' : 'smooth' });
    return;
  }
  history.pushState(null, '', '/' + r);
  const tile = a.classList.contains('tile') ? a : (S.route === 'index' ? view.querySelector(`.tile[href="/${CSS.escape(r)}"]`) : null);
  const vis = tile && tile.getBoundingClientRect().bottom > 0 && tile.getBoundingClientRect().top < innerHeight;
  openPage(r, vis ? tile : null);
});
window.addEventListener('popstate', () => {
  if (S.silent) return;
  const r = routeFromPath();
  if (r === 'cart') return;
  if (r === 'index') { if (S.route !== 'index') closePage(); }
  else if (r !== S.route) openPage(r, null);
});
function wireDetail() {
  $('#close').addEventListener('click', () => { history.pushState(null, '', '/'); closePage(); });
  view.querySelectorAll('.size').forEach((b) => b.addEventListener('click', () => {
    S.sel[b.dataset.axis] = b.dataset.val;
    view.querySelectorAll(`.size[data-axis="${CSS.escape(b.dataset.axis)}"]`).forEach((x) => x.setAttribute('aria-checked', String(x === b)));
    const v = currentVariant();
    const add = $('#add');
    if (add) { add.disabled = !v || (v.inventory !== null && v.inventory <= 0); $('#addLabel').textContent = add.disabled ? 'sold out' : 'add to cart'; if (v) { $('#addPrice').textContent = usd(v.price); $('#addPriceM').textContent = usd(v.price); } }
  }));
  const add = $('#add');
  if (add) add.addEventListener('click', () => {
    const v = currentVariant();
    if (!v) { toast('choose an option'); return; }
    store.dispatch({ type: 'ADD_COMMERCE_PRODUCT_TO_CART', payload: { product_id: v.product_id, variant_id: v.variant_id, quantity: 1 }, meta: { is_template: false } });
    toast(`added, ${S.product.name.toLowerCase()} ${Object.values(S.sel).join(', ').toLowerCase()}`);
  });
}

